"""Explain report teardown and early boot range arrays and alignment."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1845': ('점검표에 문제가 발견됐다는 표시를 붙이는 일과 고장 난 물건을 고치는 일은 달라요. 보고 끝의 상태 표시도 수리 작업은 아니에요.', '문제 상태 기록과 실제 복구를 구별하고 잠금 해제 순서를 읽습니다.', '정보 출력→끝 구분선→문제 상태 표시→보고 잠금 풀기 순서로 네 칸을 그리세요.', ['KMSAN은 준비되지 않은 메모리 값의 사용 같은 문제를 찾아 보고해요. 보고 끝에서는 dump_stack_print_info로 실행 상황에 관한 정보를 출력하고, 긴 등호 줄로 보고의 끝을 구분해요.', '이어서 add_taint를 호출해 커널에 문제가 관찰됐다는 상태 표시를 남겨요. taint는 여기서 운영체제 핵심 부분인 커널의 진단 상태를 나타내는 말이에요. 보고를 읽는 사람이 이후 상태를 해석하는 데 필요한 흔적이에요.', '이 호출은 TAINT_BAD_PAGE와 LOCKDEP_NOW_UNRELIABLE을 전달해요. 앞의 이름은 추가할 문제 표시이고 뒤의 이름은 잠금 진단 결과를 더 이상 신뢰할 수 없는 상태라는 정보를 전달해요. 잠금 진단은 코드가 잠금을 올바르게 쓰는지 살피는 기능이에요.', 'add_taint 다음에 raw_spin_unlock으로 보고용 잠금을 풀어요. 따라서 상태 표시를 추가할 때는 아직 보고 잠금 구간 안이에요. 잠금은 같은 규칙을 따르는 보고들이 공유 정보를 동시에 덮어쓰지 않게 하는 장치예요.', '상태를 표시했다고 미준비 데이터가 올바른 값으로 채워지지는 않아요. 반납한 메모리가 자동으로 다시 할당되거나 잘못된 사용이 고쳐지는 것도 아니에요. 이 코드가 하는 일은 보고와 진단 상태 기록이에요.', '종이에 네 동작의 순서를 적으면 상태 기록이 잠금 해제보다 앞인지 확인할 수 있어요. 이 순서 확인만으로 실제 여러 CPU의 동시 출력이나 잠금 진단 전체를 시험했다고 말할 수는 없어요.'], [('이 보고에서 add_taint는 보고 잠금을 풀기 전인가요, 후인가요?', ['잠금을 푼 뒤예요', '잠금을 풀기 전이에요'], '정답은 두 번째예요. add_taint 다음 줄에 raw_spin_unlock이 있어요. 보고 끝에 있다는 이유로 이미 잠금이 풀렸다고 추측하지 말고 문장 순서를 보세요.'), ('taint 표시를 추가하면 잘못된 메모리 값도 자동으로 고쳐지나요?', ['아니요. 문제가 관찰됐다는 진단 상태를 남겨요', '네. 모든 미준비 바이트를 올바른 값으로 바꿔요'], '정답은 첫 번째예요. 점검표에 표시하는 것과 물건을 수리하는 일은 달라요. 이 부분에는 데이터 값을 채워 고치는 코드가 없어요.')]), 'os1846': ('일을 마치고 잠금을 푼 뒤, 평소처럼 돌아갈지 비상 중단할지를 나눠요. 두 길이 같은 후속 작업을 한다고 생각하면 안 돼요.', '보고 잠금 해제와 panic 분기, 정상 상태 복구의 순서를 이해합니다.', '잠금 풀기 뒤에 갈림길을 그리세요. 설정 0은 상태 복구→보고 억제 해제, 설정 비영은 panic으로 연결하세요.', ['kmsan_report는 보고를 마친 뒤 raw_spin_unlock으로 보고 잠금을 먼저 풀어요. 이어 panic_on_kmsan이라는 설정값을 확인해요. 0이 아니면 panic을 호출하고, 0이면 그 호출을 건너뛰어요.', 'panic은 커널이 정상 실행을 계속할 수 없다고 처리하는 경로예요. 보통 함수처럼 호출한 다음 줄로 돌아오지 않아요. 따라서 이 함수에서 panic 뒤에 적힌 코드를 언제나 실행한다고 설명하면 안 돼요.', '설정이 0인 정상 복귀 경로에서는 user_access_restore로 앞에서 보관한 사용자 메모리 접근 상태를 복구해요. 그다음 kmsan_enable_current로 현재 작업의 보고 억제 횟수를 줄여요.', '보고 입구를 통과했을 때 억제 횟수 depth는 0이었고, 보고 시작에 disable_current가 이를 1로 올렸어요. 정상 끝에서는 enable_current가 1을 0으로 되돌려요. 보고 중 다시 보고가 시작되는 일을 막았다가 풀어 주는 짝이에요.', 'panic을 부르는 바로 그 시점에는 보고 잠금은 이미 풀렸지만, 뒤쪽의 접근 상태 복구와 억제 해제 호출에는 아직 도달하지 않았어요. 모든 정리 작업을 마친 다음 panic한다고 뭉뚱그리지 말고 각각의 위치를 보세요.', '실습용 모형에서 panic 대신 호출 여부만 기록하고 돌아오는 함수를 썼다면 그 뒤 코드까지 실행될 수 있어요. 하지만 그것은 모형의 동작이에요. 실제 커널 panic이 정상 복귀한다는 근거로 삼으면 안 돼요. 종이 갈림길로 두 경로를 비교하세요.'], [('이 보고가 panic을 호출하는 시점에 보고 잠금은 어떤 상태인가요?', ['여전히 잠겨 있어요', '이미 풀린 상태예요'], '정답은 두 번째예요. raw_spin_unlock 다음에 panic 설정을 확인해요. 잠금이 풀렸다는 사실과 뒤쪽 상태 복구까지 끝났다는 것은 서로 다른 말이에요.'), ('실제 panic 뒤에도 user_access_restore가 정상 실행된다고 보장할 수 있나요?', ['아니요. 실제 panic은 정상적으로 돌아오지 않아요', '네. 실습 모형이 돌아왔으면 실제 panic도 같아요'], '정답은 첫 번째예요. 정상 복귀 경로에서만 이어지는 복구와 비상 중단 경로를 구별해야 해요. 기록용 모형의 반환을 실제 함수의 반환으로 해석하면 안 돼요.')]), 'os1847': ('준비물이 아직 도착하지 않았다면 먼저 해야 할 일의 목록을 적어 둘 수 있어요. 부팅 중 이 코드는 검사 정보를 나중에 준비할 메모리 구간을 기록해요.', '고정 배열과 순차 탐색을 선택한 이유, 기록과 할당의 차이를 이해합니다.', '시작·끝 두 칸이 있는 목록 세 줄을 그리세요. 새 구간을 넣을 때 기존 줄을 앞에서부터 비교한다고 표시하세요.', ['부팅은 컴퓨터가 운영체제를 시작하는 과정이에요. 이른 부팅 단계에는 페이지 할당기가 아직 준비되지 않았을 수 있어요. 페이지 할당기는 메모리를 일정 크기 구역인 페이지 단위로 내주는 기능이에요.', 'kmsan_record_future_shadow_range는 나중에 KMSAN 검사 정보를 준비할 구간을 기록해요. start는 시작 주소, end는 끝 경계 주소예요. 기록한다고 그 자리에서 실제 검사 정보용 페이지를 곧바로 얻는 것은 아니에요.', 'start_end_pairs는 시작과 끝 한 쌍을 담는 고정 크기 배열이에요. NUM_FUTURE_RANGES는 128이라 128쌍을 담을 자리가 있고, future_index는 현재 사용한 항목 수를 나타내요. 저장 용량과 실제 항목 수는 달라요.', '새 구간을 넣을 때 for 반복문으로 기존 항목을 앞에서부터 살펴봐요. 이런 방법을 선형 탐색이라고 해요. 목록이 세 줄이면 필요에 따라 첫 줄, 둘째 줄, 셋째 줄을 순서대로 비교하는 방식이에요.', '원문 주석은 이 상황의 구간 수가 20개 미만이어서 더 복잡한 자료구조가 필요 없다고 설명해요. 트리는 가지를 따라 찾는 자료구조로 큰 목록에서 유리할 수 있지만, 연결과 관리 규칙도 필요해요. 작은 부팅 목록에서는 단순한 배열과 반복문을 선택한 이유가 있어요. 모든 경우에 배열이 더 빠르다는 뜻은 아니에요.', '합칠 구간을 찾으면 해당 항목을 늘리고, 없으면 새 시작·끝 쌍을 추가해요. 이 함수는 첫 병합 뒤 멈추므로 전체 목록을 끝없이 재정리하는 것은 아니에요. 이후 kmsan_init_shadow의 반복이 목록을 읽어 실제 검사 정보 준비 함수를 호출해요. 목록 작성과 자원 준비 시점을 나누어 보세요.'], [('이 코드가 미래 처리 구간을 담는 자료구조는 무엇인가요?', ['반드시 균형 이진 탐색 트리예요', '시작·끝 쌍을 담는 고정 크기 배열이에요'], '정답은 두 번째예요. start_end_pairs 선언과 앞에서부터 훑는 for 반복문이 있어요. 구간이 적은 이 상황에서는 복잡한 트리 대신 단순한 목록을 선택했어요.'), ('구간 기록 함수를 부를 때마다 실제 검사 정보용 페이지도 즉시 할당하나요?', ['아니요. 나중에 처리할 구간 목록을 적어요', '네. 언제나 즉시 페이지 할당을 실행해요'], '정답은 첫 번째예요. 이 함수는 주소 쌍을 기록하거나 합쳐요. 이후 초기화 코드가 목록을 따라 실제 준비 함수를 호출하므로 두 단계를 구별해야 해요.')]), 'os1848': ('칸 중간부터 칠해야 해도 칸 전체를 준비해야 한다면 시작 쪽은 앞 경계까지, 끝 쪽은 뒤 경계까지 넓혀야 해요.', '페이지 경계 정렬과 끝을 포함하지 않는 구간을 이해합니다.', '페이지 4096바이트에서 시작 4097, 끝 경계 8191을 표시하고 바깥 경계 4096과 8192까지 넓혀 보세요.', ['메모리는 페이지라는 일정 크기 구역으로 나누어 관리할 수 있어요. 검사 정보를 페이지 단위로 준비하려면 중간에서 시작하는 바이트 구간도 페이지 경계에 맞게 넓혀야 해요. 이 수업의 숫자 예에서는 한 페이지를 4096바이트로 정해요.', '코드의 [start, end)는 start는 포함하고 end는 포함하지 않는 표기예요. 예를 들어 [10, 13)은 10, 11, 12의 세 위치예요. 이런 구간을 반열린 구간이라고 불러요. 이전 수업의 마지막 번호까지 포함하는 보고 표기와 달라요.', 'ALIGN_DOWN은 시작을 현재 페이지의 앞 경계로 내려요. ALIGN은 끝이 경계 사이에 있으면 다음 경계로 올려요. 원래 필요한 모든 바이트가 새 구간 안에 들어오게 하려는 거예요.', '페이지 크기 4096에서 [4097, 8191)은 [4096, 8192)로 넓혀져요. 16진수 표기로는 [0x1001, 0x1fff)가 [0x1000, 0x2000)이 돼요. 0x는 숫자를 16진수로 적었다는 표시이고 같은 위치를 다른 방식으로 쓴 거예요.', '끝도 아래로 내려 4096으로 만들면 마지막 부분을 덮지 못해요. 시작을 위로 올려 8192로 잡아도 앞쪽 필요한 부분을 잃어요. 시작은 아래로, 끝은 위로 맞추는 이유가 여기에 있어요.', '끝이 이미 8192처럼 페이지 경계면 그대로 8192예요. 매번 한 페이지를 더하는 뜻은 아니에요. 새 구간도 끝은 제외하므로 [4096, 8192)는 4096바이트예요. 이 계산은 순서가 올바르고 정수 범위를 넘지 않는 유효한 입력을 전제로 해요.'], [('페이지가 4096바이트일 때 [0x1001, 0x1fff)를 바깥 경계에 맞추면 무엇인가요?', ['[0x2000, 0x1000)이에요', '[0x1000, 0x2000)이에요'], '정답은 두 번째예요. 시작 4097을 4096으로 내리고 끝 경계 8191을 8192로 올려요. 첫 선택지는 시작과 끝 순서가 뒤집혀 원래 구간을 담지 못해요.'), ('끝 경계를 위쪽 페이지 경계로 올리는 이유는 무엇인가요?', ['마지막 페이지 안의 필요한 부분까지 빠짐없이 포함하려고요', '항상 시작 페이지를 제외하려고요'], '정답은 첫 번째예요. 끝을 아래로 내리면 원래 필요했던 뒤쪽 바이트가 빠질 수 있어요. 이미 경계에 있으면 그대로 두며, 시작 페이지를 제외하는 작업은 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_457.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
